package com.finscore.backend.service;

import com.finscore.backend.dto.AnalysisResponse;
import com.finscore.backend.parser.StandardReportParser;
import com.finscore.backend.parser.StandardReportParser.ParsedReport;
import com.finscore.backend.parser.StandardReportParser.Values;
import org.springframework.stereotype.Service;
import org.springframework.web.multipart.MultipartFile;
import java.math.*;
import java.util.*;

@Service
public class AnalysisService {
    private static final int SCALE = 2;
    private static final Map<String, Integer> WEIGHTS = Map.of("REVENUE_GROWTH", 20, "NET_MARGIN", 20, "ROE", 25, "ROA", 15, "DEBT_TO_EQUITY", 20);
    private final StandardReportParser parser;
    public AnalysisService(StandardReportParser parser) { this.parser = parser; }

    public AnalysisResponse analyze(MultipartFile file) {
        ParsedReport report = parser.parse(file);
        Map<String, Values> v = report.values();
        List<AnalysisResponse.Ratio> ratios = new ArrayList<>();
        add(ratios, "CURRENT_RATIO", "Current Ratio", "LIQUIDITY", div(v, "currentAssets", "currentLiabilities"), "currentAssets / currentLiabilities", "Adequate short-term coverage");
        add(ratios, "REVENUE_GROWTH", "Revenue Growth", "TREND", growth(v, "revenue"), "(latest revenue - previous revenue) / previous revenue × 100", "Year-over-year revenue change");
        add(ratios, "NET_MARGIN", "Net Profit Margin", "PROFITABILITY", pct(v, "netIncome", "revenue"), "netIncome / revenue × 100", "Profit retained from revenue");
        add(ratios, "ROA", "Return on Assets", "PROFITABILITY", pct(v, "netIncome", "totalAssets"), "netIncome / totalAssets × 100", "Profit generated by assets");
        add(ratios, "ROE", "Return on Equity", "PROFITABILITY", pct(v, "netIncome", "shareholdersEquity"), "netIncome / shareholdersEquity × 100", "Return generated for equity holders");
        add(ratios, "DEBT_TO_EQUITY", "Debt-to-Equity", "SOLVENCY", div(v, v.containsKey("totalDebt") ? "totalDebt" : "totalLiabilities", "shareholdersEquity"), "totalDebt / shareholdersEquity", "Lower leverage is generally healthier");
        add(ratios, "EQUITY_RATIO", "Equity Ratio", "SOLVENCY", pct(v, "shareholdersEquity", "totalAssets"), "shareholdersEquity / totalAssets × 100", "Assets funded by equity");
        add(ratios, "OCF_MARGIN", "Operating Cash Flow Margin", "CASH_FLOW", pct(v, "operatingCashFlow", "revenue"), "operatingCashFlow / revenue × 100", "Cash generated from operations");
        add(ratios, "OCF_COVERAGE", "OCF / Current Liabilities", "CASH_FLOW", div(v, "operatingCashFlow", "currentLiabilities"), "operatingCashFlow / currentLiabilities", "Operating cash flow coverage");
        int supportedWeight = ratios.stream().filter(AnalysisResponse.Ratio::available).filter(r -> WEIGHTS.containsKey(r.key())).mapToInt(r -> WEIGHTS.get(r.key())).sum();
        int weighted = 0;
        List<AnalysisResponse.ComponentScore> components = new ArrayList<>();
        for (String key : List.of("REVENUE_GROWTH", "NET_MARGIN", "ROE", "ROA", "DEBT_TO_EQUITY")) {
            AnalysisResponse.Ratio metric = ratios.stream().filter(r -> r.key().equals(key)).findFirst().orElseThrow();
            int weight = WEIGHTS.get(key);
            if (metric.available()) { int points = Math.round(scoreMetric(metric) * weight / 100f); weighted += points; components.add(new AnalysisResponse.ComponentScore(key, points, weight, weight)); }
        }
        int score = supportedWeight == 0 ? 1 : Math.max(1, Math.min(100, Math.round(weighted * 100f / supportedWeight)));
        int coverage = Math.round(supportedWeight * 100f / 100f);
        String confidence = coverage >= 80 ? "HIGH" : coverage >= 60 ? "MEDIUM" : "LOW";
        String risk = score >= 80 ? "LOW" : score >= 60 ? "MODERATE" : score >= 40 ? "MEDIUM_HIGH" : score >= 20 ? "HIGH" : "VERY_HIGH";
        String riskLabel = switch (risk) { case "LOW" -> "Low Risk"; case "MODERATE" -> "Moderate Risk"; case "MEDIUM_HIGH" -> "Medium-High Risk"; case "HIGH" -> "High Risk"; default -> "Very High Risk"; };
        List<AnalysisResponse.Finding> findings = findings(ratios, v);
        List<String> warnings = new ArrayList<>(report.warnings());
        findings.stream().filter(f -> "WARNING".equals(f.severity())).map(AnalysisResponse.Finding::message).forEach(warnings::add);
        Map<String, Map<String, AnalysisResponse.FinancialValue>> data = toData(v);
        List<String> missing = WEIGHTS.keySet().stream().filter(key -> ratios.stream().noneMatch(r -> r.key().equals(key) && r.available())).toList();
        return new AnalysisResponse(UUID.randomUUID().toString(), new AnalysisResponse.Source(file.getOriginalFilename(), report.pageCount(), report.unit(), report.latestYear(), report.previousYear()), new AnalysisResponse.Company(report.company(), report.currency()), data, ratios, new AnalysisResponse.Score(score, risk, riskLabel, coverage, confidence, components), findings, new AnalysisResponse.DataQuality(missing, List.of(), warnings), true, report.company(), report.latestYear(), new AnalysisResponse.ParsedFinancialValues(latest(v,"revenue"), previous(v,"revenue"), latest(v,"netIncome"), previous(v,"netIncome"), latest(v,"totalAssets"), latest(v,"totalDebt", "totalLiabilities"), latest(v,"shareholdersEquity"), latest(v,"operatingCashFlow")), new AnalysisResponse.FinancialAnalysis(value(ratios,"REVENUE_GROWTH"), value(ratios,"NET_MARGIN"), value(ratios,"ROA"), value(ratios,"ROE"), value(ratios,"DEBT_TO_EQUITY")), new AnalysisResponse.ScoreBreakdown(points(components,"REVENUE_GROWTH"), points(components,"NET_MARGIN"), points(components,"ROE"), points(components,"ROA"), points(components,"DEBT_TO_EQUITY")), warnings, riskLabel, score);
    }

    private void add(List<AnalysisResponse.Ratio> out, String key, String label, String category, BigDecimal value, String formula, String interpretation) { boolean available = value != null; String status = !available ? "UNAVAILABLE" : status(key, value); out.add(new AnalysisResponse.Ratio(key, label, value, available ? format(key, value) : "Not available", category, status, interpretation, available, formula)); }
    private BigDecimal div(Map<String, Values> v, String n, String d) { Values a=v.get(n), b=v.get(d); if (a==null||b==null||b.latest().compareTo(BigDecimal.ZERO)==0) return null; return a.latest().divide(b.latest(), 4, RoundingMode.HALF_UP); }
    private BigDecimal pct(Map<String, Values> v, String n, String d) { BigDecimal x=div(v,n,d); return x==null?null:x.multiply(BigDecimal.valueOf(100)); }
    private BigDecimal growth(Map<String, Values> v, String key) { Values x=v.get(key); if (x==null || x.previous()==null || x.previous().compareTo(BigDecimal.ZERO)==0) return null; return x.latest().subtract(x.previous()).divide(x.previous(), 4, RoundingMode.HALF_UP).multiply(BigDecimal.valueOf(100)); }
    private String status(String key, BigDecimal x) { int s=score(key,x); return s>=70?"HEALTHY":s>=40?"WATCH":"WEAK"; }
    private int scoreMetric(AnalysisResponse.Ratio r) { return score(r.key(), r.value()); }
    private int score(String key, BigDecimal x) { double n=x.doubleValue(); return switch(key) { case "REVENUE_GROWTH" -> band(n, 0, 5, 10, 15, false); case "NET_MARGIN" -> band(n, 0, 5, 10, 20, false); case "ROE" -> band(n, 5, 10, 15, 20, false); case "ROA" -> band(n, 1, 4, 7, 10, false); case "DEBT_TO_EQUITY" -> band(n, .5, 1, 1.5, 2, true); case "CURRENT_RATIO" -> clamp((n-0.5)*50); case "EQUITY_RATIO" -> clamp(n*2); case "OCF_MARGIN" -> clamp((n+5)*5); case "OCF_COVERAGE" -> clamp((n-0.2)*45); default -> 50; }; }
    private int band(double n, double a, double b, double c, double d, boolean inverse) { if (inverse) { if (n < a) return 100; if (n < b) return 80; if (n < c) return 60; if (n < d) return 40; return 15; } if (n > d) return 100; if (n >= c) return 80; if (n >= b) return 60; if (n >= a) return 40; return 15; }
    private int clamp(double x) { return (int)Math.max(0, Math.min(100, Math.round(x))); }
    private String format(String key, BigDecimal x) { return (key.equals("CURRENT_RATIO")||key.equals("DEBT_TO_EQUITY")||key.equals("OCF_COVERAGE")) ? x.setScale(2,RoundingMode.HALF_UP)+"x" : x.setScale(2,RoundingMode.HALF_UP)+"%"; }
    private Map<String, Map<String, AnalysisResponse.FinancialValue>> toData(Map<String, Values> v) { Map<String, Map<String, AnalysisResponse.FinancialValue>> m=new LinkedHashMap<>(); Map<String,AnalysisResponse.FinancialValue> income=new LinkedHashMap<>(), balance=new LinkedHashMap<>(), cash=new LinkedHashMap<>(); for (String k:List.of("revenue","operatingProfit","netIncome")) put(income,k,v); for (String k:List.of("currentAssets","currentLiabilities","totalAssets","totalLiabilities","shareholdersEquity")) put(balance,k,v); for (String k:List.of("operatingCashFlow","capitalExpenditure")) put(cash,k,v); m.put("incomeStatement",income);m.put("balanceSheet",balance);m.put("cashFlow",cash);return m; }
    private void put(Map<String,AnalysisResponse.FinancialValue> m,String k,Map<String,Values> v){Values x=v.get(k);if(x!=null)m.put(k,new AnalysisResponse.FinancialValue(x.latest(),x.previous()));}
    private BigDecimal latest(Map<String,Values> v,String... keys){for(String k:keys){Values x=v.get(k);if(x!=null)return x.latest();}return null;}
    private BigDecimal previous(Map<String,Values> v,String k){Values x=v.get(k);return x==null?null:x.previous();}
    private BigDecimal value(List<AnalysisResponse.Ratio> rs,String key){return rs.stream().filter(r->r.key().equals(key)).findFirst().map(AnalysisResponse.Ratio::value).orElse(null);}
    private Integer points(List<AnalysisResponse.ComponentScore> cs,String key){return cs.stream().filter(c->c.key().equals(key)).findFirst().map(AnalysisResponse.ComponentScore::score).orElse(null);}
    private List<AnalysisResponse.Finding> findings(List<AnalysisResponse.Ratio> r, Map<String,Values> v) { List<AnalysisResponse.Finding> f=new ArrayList<>(); Values ocf=v.get("operatingCashFlow"); if(ocf!=null&&ocf.latest().compareTo(BigDecimal.ZERO)>0) f.add(new AnalysisResponse.Finding("STRENGTH","INFO","Operating cash flow is positive.")); if(ocf==null) f.add(new AnalysisResponse.Finding("INFO","WARNING","Operating cash flow was not found in the uploaded report.")); for(AnalysisResponse.Ratio x:r) if(x.available()&&x.status().equals("WEAK")) f.add(new AnalysisResponse.Finding("CONCERN","WARNING",x.label()+" is in a weak range.")); return f; }
}
